function voiceSettingsFormHTML(mode='edit',talk=false){
 if(mode==='edit')return voiceSettingsFormHTML('create',talk)
  .replace('id="voice-create-form"','id="voice-settings-form"')
  .replace('방 만들기</button>','저장</button>')
  .replace('<button type="submit" class="primary-button voice-settings-save">','<footer class="room-settings-footer"><button type="button" class="small-button" data-voice="dismiss">취소</button><button type="submit" class="primary-button voice-settings-save">')
  .replace('data-auto-title>자동 제목 생성','data-auto-title aria-label="방 제목 자동 생성">'+voiceGlyph('wave'))
  .replace(/<p class="field-help">기본 무료 테마 3종[\s\S]*?<\/p>/,'')
  .replace('</form>','</footer></form>');
 return `<form id="${mode==='create'?'voice-create-form':'voice-settings-form'}">${mode==='create'?'<div class="live-form-fields">'+liveRoomTypeFields():'<label>방 유형<select name="mode"><option value="talk">토킹룸</option><option value="karaoke">라이브 노래방</option></select></label><p class="field-help">방 유형을 바꿔 저장하면 현재 노래와 예약이 종료됩니다. 참여자와 채팅은 그대로 유지돼요.</p>'}<label>방 제목${mode==='create'?'<span class="live-title-row">':''}<input name="title" maxlength="60" ${talk&&mode==='create'?'':'required'}>${mode==='create'?'<button class="small-button" type="button" data-auto-title>자동 제목 생성</button></span>':''}</label><fieldset><legend>방 공개 설정</legend><div class="voice-visibility"><label><input type="radio" name="visibility" value="public">${voiceGlyph('globe')}<strong>${talk?'공개':'공개방'}</strong><small>누구나 참여 가능</small></label><label><input type="radio" name="visibility" value="private">${voiceGlyph('lock')}<strong>${talk?'비공개':'비공개방'}</strong><small>초대된 사람만</small></label><label><input type="radio" name="visibility" value="crew"${mode==='create'?' aria-describedby="voice-create-crew-status"':''}>${voiceGlyph('people')}<strong>${talk?'크루':'크루만'}</strong><small>내 크루만 참여 가능</small></label><label><input type="radio" name="visibility" value="followers">${voiceGlyph('person')}<strong>${talk?'팔로우':'팔로우만'}</strong><small>내 팔로워만 참여 가능</small></label></div></fieldset>${mode==='create'?'<input type="hidden" name="crew_id"><p class="voice-crew-setting field-help" id="voice-create-crew-status" aria-live="polite" hidden></p>':'<label class="voice-crew-setting">연결할 크루<select name="crew_id" id="voice-settings-crew"><option value="">크루 선택</option></select></label>'}${mode==='create'?'<fieldset class="live-capacity"><legend>최대 참여 인원</legend><div class="live-capacity-controls"><div class="live-capacity-presets" role="group" aria-label="참여 인원 빠른 선택"><button class="small-button" type="button" data-capacity="8" aria-pressed="false">8명</button><button class="small-button" type="button" data-capacity="15" aria-pressed="false">15명</button><button class="small-button" type="button" data-capacity="30" aria-pressed="true">30명</button></div><label class="live-capacity-input"><span class="sr-only">참여 인원 직접 입력</span><input type="number" name="max_members" min="2" max="30" step="1" inputmode="numeric" value="30" required aria-describedby="voice-create-capacity-help"><span aria-hidden="true">명</span></label></div><p class="field-help" id="voice-create-capacity-help">2~30명까지 입력할 수 있어요.</p></fieldset>':'<label>최대 참여 인원<select name="max_members"><option value="2">2명</option><option value="3">3명</option><option value="4">4명</option><option value="5">5명</option><option value="6">6명</option><option value="7">7명</option><option value="8">8명</option><option value="9">9명</option><option value="10">10명</option><option value="11">11명</option><option value="12">12명</option><option value="13">13명</option><option value="14">14명</option><option value="15">15명</option><option value="16">16명</option><option value="17">17명</option><option value="18">18명</option><option value="19">19명</option><option value="20">20명</option><option value="21">21명</option><option value="22">22명</option><option value="23">23명</option><option value="24">24명</option><option value="25">25명</option><option value="26">26명</option><option value="27">27명</option><option value="28">28명</option><option value="29">29명</option><option value="30">30명</option></select></label>'}${talk&&mode!=='create'?'<input type="hidden" name="theme_sku" value="navy"><button class="small-button talk-theme-select" type="button" data-voice="theme-picker">배경 테마 선택</button>':`<fieldset><legend>테마 선택</legend><div class="voice-backgrounds"><label data-background="navy"><input type="radio" name="background" value="navy"><span>차분한 다크</span></label><label data-background="sunset"><input type="radio" name="background" value="sunset"><span>차분한 노을</span></label><label data-background="night"><input type="radio" name="background" value="night"><span>밤하늘</span></label></div></fieldset><p class="field-help">기본 무료 테마 3종 · 보유한 유료 테마를 선택할 수 있어요. <a href="#gifts/themes">상점에서 보기</a></p>`}<label>방 공지<span class="voice-notice-input"><textarea name="announcement" maxlength="200" rows="3"></textarea><output id="voice-notice-length">0/200</output></span></label>${mode==='create'?'</div><p class="form-error" role="alert"></p>':''}<button type="submit" class="primary-button voice-settings-save">${mode==='create'?'방 만들기':talk?'변경 사항 저장':'저장하기'}</button></form>`; }
