function voiceRoomHTML(id,talk=true){
 const talkHeader=`<header class="room-header"><div class="room-heading"><h1 id="voice-title">${talk?'토킹룸':'라이브 노래방'}</h1><small aria-label="방 개설 후 경과 시간">${icon('clock')}<time data-room-elapsed></time></small></div><nav aria-label="방 메뉴">${[['inbox','메시지','mail'],['participants','참여자','people'],['sound','소리 설정','talkSliders'],['share','공유','share'],['settings','방 설정','talkSettings'],['leave','방 나가기','leave']].map(([action,label,glyph])=>`<button type="button" class="voice-icon-button" data-voice="${action}" aria-label="${label}" title="${label}">${voiceGlyph(glyph)}</button>`).join('')}</nav></header>`;
 const central=`<div class="talk-central" aria-label="중앙패널"><div id="talk-request" role="status"></div><button type="button" data-voice="release-mic" hidden>내려오기</button><button type="button" class="small-button voice-unlock-audio" data-voice="resume-audio" title="마이크를 켜거나 좌석에 올라가지 않아도 대화를 들을 수 있어요." hidden>대화 듣기</button><button type="button" data-voice="toggle-mic" aria-label="내 마이크 켜기" aria-pressed="false">${voiceGlyph('muted')}</button></div>`;
 const close='';
 return `<section class="voice-room${talk?' talking-room':''}" data-voice-room="${esc(id)}">${talkHeader}<div id="voice-entry" hidden><button id="voice-join" class="primary-button">다시 연결</button></div><div id="voice-content" hidden><div class="voice-columns"><section class="voice-stage"><div id="voice-music-player" class="voice-music-mini" aria-label="공동 음악"></div>${talk?'':`<button type="button" class="small-button voice-unlock-audio" data-voice="resume-audio" title="마이크를 켜거나 좌석에 올라가지 않아도 대화를 들을 수 있어요." hidden>대화 듣기</button>`}<p class="room-connection"><span id="voice-status" role="status">연결하는 중…</span></p><div id="voice-seats" class="voice-seats"></div>${talk?central:''}${talk?'':'<button class="small-button voice-cancel-request" data-voice="cancel-mic" hidden>신청 취소</button>'}<p id="voice-mic-note" class="quiet"></p><div id="voice-listeners" class="voice-listeners"></div></section><section class="voice-chat-panel"><aside id="voice-announcement" class="voice-announcement" hidden><span class="voice-notice-icon">${voiceGlyph('megaphone')}</span><div><strong>방 공지</strong><p id="voice-announcement-text"></p></div></aside><div id="voice-seat-invitation" role="status" hidden></div><div id="voice-chat" class="voice-chat" aria-live="polite" aria-relevant="additions"></div><dialog id="voice-emoji-picker" class="cat-picker voice-emoji-picker" aria-label="고양이 미니이모티콘" hidden></dialog><form id="voice-chat-form"><label class="sr-only" for="voice-message">메시지</label><div class="talk-message-field"><textarea id="voice-message" name="body" placeholder="${talk?'메시지…':'메시지를 입력하세요…'}" maxlength="500" required rows="1" enterkeyhint="send" aria-describedby="voice-chat-help"></textarea><span id="voice-chat-help" class="sr-only">Enter로 전송, Shift+Enter로 줄바꿈.</span><button type="button" class="voice-icon-button" data-voice="emoji" aria-haspopup="dialog" aria-label="이모티콘" aria-expanded="false" aria-controls="voice-emoji-picker">${voiceGlyph('smile')}</button></div><button type="submit" class="voice-icon-button talk-send" aria-label="메시지 보내기">${voiceGlyph('send')}</button><button type="button" class="voice-icon-button" data-voice="gift" aria-label="선물 보내기">${voiceGlyph('present')}</button></form></section></div>${talk?'<div class="talk-gift-effect" aria-hidden="true" hidden></div>':'<div id="voice-gift-animation" class="voice-gift-animation" role="status" hidden></div>'}
 <dialog id="voice-sound" class="voice-sheet compact-popup">${close}<header class="voice-sheet-heading"><span>${icon('mic')}</span><div><h2>소리 설정</h2>${talk?'':'<p>방송과 음성 대화에 사용할 마이크와 소리를 설정하세요.</p>'}</div></header><p id="voice-sound-current" class="quiet voice-current-song"></p>
 <section class="voice-audio-card"><h3>${icon('mic')} 마이크 입력 볼륨 <output data-value-for="voice-input-gain">100%</output></h3><label class="voice-range-row">${icon('volume')}<input id="voice-input-gain" aria-label="내 마이크 음량" type="range" min="0" max="100" value="100">${icon('volume')}</label></section>
 <section class="voice-audio-card voice-toggle-card"><div><h3>${icon('headphones')} 내 목소리 모니터링</h3><p>내 목소리를 실시간으로 들을 수 있어요. 이어폰 사용을 권장해요.</p></div><label class="voice-switch"><input id="voice-monitor" type="checkbox" aria-label="내 목소리 모니터링"><span></span></label></section>
 <section class="voice-audio-card voice-toggle-card"><div><h3>${voiceGlyph('wave')} 노이즈 제거</h3><p>주변 소음을 줄여 내 목소리를 더 또렷하게 전달해요.</p></div><label class="voice-switch"><input id="voice-noise" type="checkbox" checked aria-label="노이즈 제거"><span></span></label></section>
 <section class="voice-audio-card voice-toggle-card"><div><h3>${voiceGlyph('wave')} 에코 제거</h3><p>스피커 소리가 마이크에 다시 들어오는 것을 줄여요.</p></div><label class="voice-switch"><input id="voice-echo" type="checkbox" checked aria-label="에코 제거"><span></span></label></section>
 <section class="voice-audio-card voice-effect-card"><div><h3>${icon('sliders')} 에코 / 리버브 효과</h3><p>목소리에 은은한 공간감을 더해보세요.</p></div><label><span>에코 스타일</span><select id="voice-preset"><option value="studio">스튜디오</option><option value="hall">홀</option><option value="karaoke">노래방</option></select></label><label class="voice-reverb-row">강도 <input id="voice-reverb" aria-label="에코 강도" type="range" min="0" max="100" value="25"><output data-value-for="voice-reverb">25%</output></label></section>
 <section id="voice-host-audio" class="voice-audio-card"><h3>${voiceGlyph('playlist')} 공유 음악 볼륨 <output data-value-for="voice-room-volume">70%</output></h3><p>방에서 함께 듣는 음악의 기준 볼륨을 조절해요.</p><label class="voice-range-row">${icon('volume')}<input id="voice-room-volume" aria-label="방 전체 음악 볼륨" type="range" min="0" max="100" step="1">${icon('volume')}</label><details><summary>음악과 목소리 균형</summary><label>목소리 중심 ↔ 음악 중심 <input id="voice-balance" type="range" min="0" max="100" step="1"></label><button class="small-button" data-voice="music-picker">플레이리스트 열기</button></details></section>
 <section class="voice-audio-card voice-mic-test"><h3>${voiceGlyph('wave')} 마이크 테스트</h3><p>마이크에 대고 말해보세요. 입력되는 목소리가 실시간으로 표시돼요.</p><div class="voice-test-controls"><meter id="voice-input-meter" min="0" max="1" value="0" aria-label="실제 마이크 입력 레벨"></meter><button type="button" class="small-button" data-voice="mic-test">${icon('mic')} 테스트 시작</button></div></section>
 <details class="voice-audio-extra"><summary>입력 장치 · 개인 청취 볼륨</summary><label>내 마이크 입력 장치<select id="voice-input"><option value="">기본 마이크</option></select></label><label>출력 장치<select id="voice-output"><option value="">기본 스피커 / 이어폰</option></select></label><label>개인 음악 볼륨 <input id="voice-music-volume" type="range" min="0" max="100" value="100"></label><label>참가자 목소리 <input id="voice-listen-volume" type="range" min="0" max="100" value="100"></label><p class="quiet">장치가 지원하지 않는 효과는 원음으로 연결돼요.</p></details></dialog>
 <dialog id="voice-members" class="voice-sheet compact-popup" aria-label="참여자"><div id="voice-members-list"></div><div id="voice-member-tools" hidden></div></dialog>
 <dialog id="voice-room-settings" class="voice-sheet compact-popup">${close}<header class="voice-sheet-heading"><span>${voiceGlyph('home')}</span><h2>방 설정</h2></header>${voiceSettingsFormHTML("edit",talk)}<p id="voice-settings-readonly" class="quiet" hidden>방장이 설정을 변경할 수 있어요.</p><button type="button" class="small-button" data-voice="close" hidden>토킹룸 종료</button></dialog>
 <dialog id="voice-music-sheet" class="voice-sheet compact-popup">${close}<header class="voice-sheet-heading voice-playlist-heading"><h2>플레이리스트</h2></header><form id="voice-music-search"><label class="sr-only" for="voice-music-query">곡명 · 아티스트</label>${icon('search')}<input id="voice-music-query" placeholder="노래 제목이나 아티스트를 검색해보세요." maxlength="100"><button class="small-button" aria-label="음악 검색">검색</button></form><p class="quiet voice-music-rights">권리자가 공동 감상을 허용한 원곡만 재생할 수 있어요.</p><header id="voice-results-heading" class="voice-results-heading" hidden><h3>검색 결과</h3><small id="voice-search-count"></small></header><div id="voice-music-results"></div><section id="voice-playlist-empty" class="voice-playlist-empty"><span>♫</span><h3>아직 추가된 음악이 없어요</h3><p>위 검색창에서 노래를 찾아 + 버튼으로 추가해 주세요.</p><small>추가된 음악이 있으면 이곳에 재생목록이 나타납니다.</small></section><section id="voice-queue-area" hidden><header class="voice-queue-heading"><h3>내 플레이리스트 <small id="voice-queue-count"></small></h3><button type="button" data-voice="music-clear">${voiceGlyph('trash')} 전체 삭제</button></header><div class="voice-popup-player"><div id="voice-popup-current"></div><div class="voice-music-transport"><button data-voice="music-previous" aria-label="이전 곡">${voiceGlyph('previous')}</button><button data-voice="music-play" aria-label="음악 재생">${talk?voiceGlyph('talkPlay'):icon('audio-play')}</button><button data-voice="music-pause" aria-label="음악 일시정지">${talk?voiceGlyph('talkPause'):icon('pause')}</button><button data-voice="music-next" aria-label="다음 곡">${voiceGlyph('next')}</button><button data-voice="music-repeat">반복 끔</button><button data-voice="music-stop">종료</button><label>재생 위치 <input id="voice-music-seek" type="range" min="0" max="0" value="0" step="1"></label></div><div id="voice-playlist-personal"><label>개인 음악 볼륨<input id="voice-playlist-volume" type="range" min="0" max="100" value="100"></label></div></div><h3 id="voice-queue-heading" hidden>재생목록</h3><div id="voice-music-queue"></div></section></dialog>
 ${`<dialog id="talk-volume" class="voice-sheet compact-popup" aria-labelledby="talk-volume-title">${close}<h2 id="talk-volume-title">개인 듣기 볼륨</h2><p>내 기기에서 들리는 음악에만 적용돼요.</p><label for="voice-personal-volume">음악 볼륨 <output data-value-for="voice-personal-volume">100%</output></label><input id="voice-personal-volume" type="range" min="0" max="100" value="100"><button type="button" data-voice="personal-mute" aria-pressed="false">개인 음소거</button></dialog>
 <dialog id="talk-themes" class="voice-sheet compact-popup" aria-labelledby="talk-theme-title">${close}<h2 id="talk-theme-title">배경 테마 선택</h2><form id="talk-theme-choices"><div class="voice-backgrounds"></div><footer><button type="button" data-voice="dismiss">취소</button><button type="submit" class="primary-button">선택</button></footer></form></dialog>
 <dialog id="talk-leave" class="voice-sheet compact-popup" aria-labelledby="talk-leave-title">${close}<p class="popup-prompt" id="talk-leave-title">방에서 나갈까요?</p><footer><button type="button" data-voice="dismiss">취소</button><button type="button" data-voice="confirm-leave" class="primary-button">나가기</button></footer></dialog>`}
 <dialog id="voice-seat-picker" class="voice-sheet compact-popup">${close}<h2>좌석 초대</h2><div id="voice-seat-candidates"></div></dialog><dialog id="voice-kick-confirm" class="voice-sheet compact-popup">${close}<p class="popup-prompt">참여자를 내보낼까요?</p><p>방에서 나가며 기존 정책에 따라 1분 동안 재입장할 수 없어요.</p><button class="primary-button" data-voice="confirm-kick">강퇴</button></dialog><dialog id="room-inbox" aria-label="메시지" class="room-inbox voice-sheet compact-popup"></dialog><dialog id="voice-invite-sheet" class="voice-sheet compact-popup" aria-label="방 공유"><div class="room-share-summary"><strong data-share-title></strong><span data-share-type></span></div><form id="voice-invite-form"><label>팔로우 검색<input id="room-share-query" type="search" placeholder="닉네임 검색" autocomplete="off"></label><div id="room-share-people" aria-live="polite"></div><button type="button" class="small-button" id="room-share-more" hidden>더 보기</button><p id="room-share-result" role="status"></p><footer><span id="room-share-count">0명 선택</span><button type="submit" class="primary-button">보내기</button></footer></form></dialog>
 <dialog id="voice-gift-sheet" class="voice-sheet">${close}<h2>선물 보내기</h2><form id="voice-gift-form"><label>받는 사람 <select name="profile_id" required id="voice-gift-target"></select></label><label>선물 <select name="gift_type">${AifectGifts.GIFT_CATALOG.map(g=>`<option value="${esc(g.id)}">${esc(g.name)} · ${number(g.gold)} G</option>`).join('')}</select></label><label>수량 <input name="quantity" type="number" min="1" max="100" value="1" required></label><p id="voice-gift-summary"></p><button class="primary-button">골드 선물 보내기</button><p class="quiet">기존 프로필 선물 정산 기준이 적용돼요.</p><p id="voice-gift-result" role="status"></p></form></dialog></div></section>`;
}
